import java.util.Scanner;

public class Main {
    public static long getGCD(int a, int b) {
        while (b != 0) {
            int temp = a % b;
            a = b;
            b = temp;
        }
        return a;
    }

    public static long getLCM(int a, int b) {
        return (long) a * b / getGCD(a, b);
    }

    public static double calculateDifference(int x1, int y1, int x2, int y2) {
        long l = getLCM(y1, y2);
        long diff = Math.abs(l / y1 * x1 - l / y2 * x2);
        return (double) diff / l;
    }

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        int x = scanner.nextInt();
        int y = scanner.nextInt();
        int n = scanner.nextInt();
        double bestRatio = 1e15;
        int bestB = 1;
        double baseRatio = (double) x / y;

        for (int i = 1; i <= n; ++i) {
            int low = 1, high = 1000000;
            while (high - low > 1) {
                int mid = (low + high) / 2;
                double ratioMid = (double) mid / i;
                if (ratioMid < baseRatio)
                    low = mid;
                else
                    high = mid;
            }
            int candidate = low;
            double diffLeft = calculateDifference(candidate, i, x, y);
            double diffRight = calculateDifference(high, i, x, y);
            int chosen = (diffLeft < diffRight) ? candidate : high;
            double currentDiff = calculateDifference(chosen, i, x, y);
            double currentBest = calculateDifference(bestB, bestB, x, y);
            if (currentDiff < currentBest) {
                bestB = i;
                bestRatio = (double) chosen / i;
            }
        }
        System.out.println(bestB + "/" + n);
        scanner.close();
    }
}
